var s={en:`A repair company tracks clients, visits, quotations, employees and invoices. Dispatchers schedule jobs; managers approve discounts and review reports.`,ua:`Сервісна компанія веде клієнтів, виїзди, кошториси, працівників і рахунки. Диспетчери планують роботи; менеджери погоджують знижки й дивляться звіти.`};var i={en:[`Draw domain modules, operator and manager roles, audit and reporting.`,`Define an access matrix for visits and discount approval.`,`Show background integrations without blocking critical writes.`],ua:[`Намалюй доменні модулі, ролі, аудит і звіти.`,`Визнач матрицю прав для візитів і знижок.`,`Покажи фонові інтеграції без блокування критичних записів.`]};var n=[{en:`Sensitive writes pass backend authorization.`,ua:`Чутливі зміни проходять серверну перевірку прав.`},{en:`Approvals and edits generate traceable audit records.`,ua:`Погодження й редагування породжують аудит.`}];var r={scenario:s,tasks:i,checks:n};export{n as checks,r as default,s as scenario,i as tasks};